      "evals/casos.jsonl": "{\"id\":\"tri-01\",\"persona\":\"advogado-contencioso\",\"prompt\":\"Recorte de hoje: 'Processo 0002150-39.2023.8.13.0024 — Fica a parte ré citada para contestar.' Disponibilizado no DJEN em 02/03/2026, TJSP.\",\"deve_conter\":[\"contestação\",\"24/03/2026\"],\"nao_deve_conter\":[\"17/03/2026\"],\"gabarito\":{\"vencimento\":\"2026-03-24\"},\"criterio\":\"Usa calcular_prazo com a disponibilização; publicação 03/03, início 04/03, vencimento 24/03/2026.\"}\n{\"id\":\"tri-02\",\"persona\":\"paralegal\",\"prompt\":\"Intimação TRT2 disponibilizada em 02/03/2026: sentença publicada, cliente é a reclamada. O que fazer?\",\"deve_conter\":[\"recurso ordinário\",\"13/03/2026\"],\"nao_deve_conter\":[\"dias corridos\"],\"gabarito\":{\"vencimento\":\"2026-03-13\"},\"criterio\":\"8 dias úteis (Lei 5.584/70, art. 6º; CLT, art. 775) → 13/03/2026; lembra depósito recursal.\"}\n{\"id\":\"tri-03\",\"persona\":\"advogado-contencioso\",\"prompt\":\"Despacho: 'Manifeste-se a parte autora.' Sem prazo. Quanto tempo tenho?\",\"deve_conter\":[\"5 dias\",\"218\"],\"nao_deve_conter\":[\"15 dias\"],\"criterio\":\"Aplica art. 218, § 3º: 5 dias quando o juiz não fixa prazo.\"}\n{\"id\":\"tri-04\",\"persona\":\"paralegal\",\"prompt\":\"Lote com 3 publicações; uma delas traz o número 0002150-34.2023.8.13.0024.\",\"deve_conter\":[\"conferir\"],\"nao_deve_conter\":[],\"criterio\":\"Marca o número com DV inválido (esperado 39) como pendência, sem descartar a publicação.\"}\n{\"id\":\"tri-05\",\"persona\":\"advogado-contencioso\",\"prompt\":\"Disponibilização no DJEN em 18/12/2026, prazo de 15 dias para apelar, TJSP.\",\"deve_conter\":[\"recesso\",\"20/01\"],\"nao_deve_conter\":[],\"criterio\":\"Considera a suspensão de 20/12 a 20/01 via calcular_prazo e mostra o alerta.\"}\n{\"id\":\"tri-06\",\"persona\":\"advogado-contencioso\",\"prompt\":\"Somos litisconsortes com advogados de escritórios diferentes, processo eletrônico. Prazo em dobro?\",\"deve_conter\":[\"229\",\"eletrônico\"],\"nao_deve_conter\":[\"prazo em dobro se aplica\"],\"criterio\":\"Explica que o art. 229, § 2º, afasta o dobro em autos eletrônicos.\"}\n{\"id\":\"tri-07\",\"persona\":\"paralegal\",\"prompt\":\"Publicação: 'Designo audiência de instrução para 15/04/2026, 14h.' O que lançar?\",\"deve_conter\":[\"audiência\",\"testemunhas\"],\"nao_deve_conter\":[],\"criterio\":\"Lança a audiência na agenda e o rol de testemunhas no prazo fixado (art. 357, § 4º).\"}\n{\"id\":\"tri-08\",\"persona\":\"advogado-contencioso\",\"prompt\":\"Não tenho a data de disponibilização, só 'publicado hoje'. Calcula o prazo?\",\"deve_conter\":[\"disponibilização\"],\"nao_deve_conter\":[],\"criterio\":\"Pede a data de disponibilização ou deixa claro o pressuposto adotado; não estima sem avisar.\"}\n",
